import {request} from './cloud-ui.mjs';
import {updateModelPicker,bindModelRefresh} from './model-picker.mjs';
import {exampleVideo,validateVideoProject} from './video-project.mjs';
const $=selector=>document.querySelector(selector);let project=null,elapsed=0,playing=false,lastFrame=0,raf=0;
const clamp=(n,a=0,b=1)=>Math.max(a,Math.min(b,n));
const clock=value=>{const seconds=Math.max(0,Math.floor(value));return `${Math.floor(seconds/60)}:${String(seconds%60).padStart(2,'0')}`};
async function refreshStatus(){const state=await request('/api/status');updateModelPicker($('#model'),state);$('#connection-state').textContent=state.configured?'Connexion Ollama prête.':'Clé absente : configure-la dans l’Atelier Ollama avant une génération.';$('#connection-state').classList.toggle('error',!state.configured);$('#generate').disabled=!state.configured||!$('#model').value;}
function sceneAt(time){let start=0;for(let i=0;i<project.scenes.length;i++){const end=start+project.scenes[i].duration;if(time<end||i===project.scenes.length-1)return {scene:project.scenes[i],index:i,start,progress:clamp((time-start)/project.scenes[i].duration)};start=end}}
function timing(scene,progress){const local=progress*scene.duration,enter=clamp(local/.42),leave=clamp((scene.duration-local)/.32),out=value=>1-(1-clamp(value))**3,back=value=>{const x=clamp(value)-1;return 1+2.7*x*x*x+1.7*x*x};return {local,enter:out(enter),leave:out(leave),kicker:out(local/.24),title:back((local-.08)/.38),body:out((local-.28)/.42)}}
function render(){if(!project)return;const {scene,index,progress}=sceneAt(elapsed),motion=timing(scene,progress),theme=project.theme;const stage=$('#stage');stage.style.cssText=`--scene-bg:${theme.background};--scene-fg:${theme.foreground};--scene-accent:${theme.accent};--scene-muted:${theme.muted};background:${theme.background};color:${theme.foreground}`;stage.replaceChildren(renderScene(scene,motion,progress));$('#timeline').value=Math.round(elapsed/project.duration*1000);$('#time').value=`${clock(elapsed)} / ${clock(project.duration)}`;[...$('#scene-list').children].forEach((item,i)=>item.firstElementChild.classList.toggle('active',i===index));}
function node(tag,className,text){const element=document.createElement(tag);if(className)element.className=className;if(text!==undefined)element.textContent=text;return element}
function renderScene(scene,motion,progress){const root=node('article',`video-scene ${scene.type}-scene`),direction=scene.transition==='slide'?1:0;for(const [key,value] of Object.entries({'--scene-opacity':Math.min(motion.enter,motion.leave),'--scene-x':`${(1-motion.enter)*direction*13-(1-motion.leave)*direction*7}%`,'--scene-y':`${(1-motion.enter)*(direction?0:3)}%`,'--scene-scale':scene.transition==='zoom'?(.84+motion.enter*.16)*(.96+motion.leave*.04):1,'--kicker-reveal':motion.kicker,'--title-reveal':motion.title,'--body-reveal':motion.body,'--accent-reveal':motion.enter,'--scene-progress':progress}))root.style.setProperty(key,value);root.append(node('i','scene-orb'),node('i','scene-rail'),node('span','scene-kicker',scene.type==='diagram'?'SCHÉMA':scene.type==='chart'?'DONNÉES':scene.type==='summary'?'À RETENIR':'NOCTURNE EXPLIQUE'),node('h2','',scene.title));
 if(scene.body)root.append(node('p','body',scene.body));if(scene.type==='quote')root.append(node('p','quote-source','— '+scene.source));
 if(scene.type==='diagram')root.append(renderDiagram(scene,motion.local));if(scene.type==='chart')root.append(renderChart(scene,motion.local));return root}
function renderDiagram(scene,local){const box=node('div','diagram'),positions=scene.nodes.map((_,i)=>{const a=-Math.PI/2+i*Math.PI*2/scene.nodes.length;return {x:50+Math.cos(a)*34,y:50+Math.sin(a)*35}}),svg=document.createElementNS('http://www.w3.org/2000/svg','svg');scene.links.forEach(([a,b],i)=>{const line=document.createElementNS(svg.namespaceURI,'line');for(const [key,value] of Object.entries({x1:positions[a].x+'%',y1:positions[a].y+'%',x2:positions[b].x+'%',y2:positions[b].y+'%'}))line.setAttribute(key,value);line.style.setProperty('--line-reveal',clamp((local-.55-i*.12)/.35));svg.append(line)});box.append(svg);scene.nodes.forEach((item,i)=>{const el=node('div','diagram-node',item.label);el.style.left=positions[i].x+'%';el.style.top=positions[i].y+'%';el.style.setProperty('--node-reveal',clamp((local-.4-i*.12)/.32));box.append(el)});return box}
function renderChart(scene,local){const chart=node('div','chart'),max=Math.max(...scene.values.map(item=>item.value),1);scene.values.forEach((item,i)=>{const bar=node('div','chart-bar');bar.style.setProperty('--height',15+item.value/max*75);bar.style.setProperty('--bar-reveal',clamp((local-.4-i*.12)/.45));bar.append(node('span','',`${item.value}${scene.unit?' '+scene.unit:''}`),node('small','',item.label));chart.append(bar)});return chart}
function load(value){project=validateVideoProject(value);elapsed=0;playing=false;cancelAnimationFrame(raf);$('#stage-wrap').className=`stage-wrap ${project.format}`;$('#video-meta').textContent=`${project.title} · ${project.duration.toFixed(1)} s`;$('#play').disabled=false;$('#timeline').disabled=false;$('#download').disabled=false;$('#export-video').disabled=!window.MediaRecorder||!HTMLCanvasElement.prototype.captureStream;$('#play').textContent='Lire';$('#export-status').textContent=$('#export-video').disabled?'Ce navigateur ne permet pas l’export vidéo local.':'';$('#scene-list').replaceChildren(...project.scenes.map((scene,i)=>{const li=node('li'),button=node('button','',`${i+1}. ${scene.title}`);button.addEventListener('click',()=>{elapsed=project.scenes.slice(0,i).reduce((sum,s)=>sum+s.duration,0);render()});li.append(button);return li}));render()}
function tick(now){if(!playing)return;elapsed=Math.min(project.duration,elapsed+(now-lastFrame)/1000);lastFrame=now;render();if(elapsed>=project.duration){playing=false;$('#play').textContent='Rejouer';return}raf=requestAnimationFrame(tick)}
$('#play').addEventListener('click',()=>{if(playing){playing=false;cancelAnimationFrame(raf);$('#play').textContent='Lire';return}if(elapsed>=project.duration)elapsed=0;playing=true;lastFrame=performance.now();$('#play').textContent='Pause';raf=requestAnimationFrame(tick)});$('#timeline').addEventListener('input',event=>{elapsed=project.duration*Number(event.target.value)/1000;render()});
$('#example').addEventListener('click',()=>load(exampleVideo));$('#download').addEventListener('click',()=>{const blob=new Blob([JSON.stringify(project,null,2)],{type:'application/json'}),link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download=(project.title.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')||'video')+'.json';link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000)});
const slug=()=>project.title.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')||'video';
function rounded(ctx,x,y,w,h,r){ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fill();ctx.stroke()}
function wrapped(ctx,value,x,y,maxWidth,lineHeight,maxLines=6){const words=value.split(/\s+/),lines=[];let line='';for(const word of words){const test=line?line+' '+word:word;if(ctx.measureText(test).width>maxWidth&&line){lines.push(line);line=word}else line=test}if(line)lines.push(line);lines.slice(0,maxLines).forEach((text,i)=>ctx.fillText(i===maxLines-1&&lines.length>maxLines?text+'…':text,x,y+i*lineHeight));return Math.min(lines.length,maxLines)*lineHeight}
function canvasScene(ctx,width,height,time){const {scene,progress}=sceneAt(time),theme=project.theme,motion=timing(scene,progress),vertical=height>width*1.2,scale=width/1080,pad=width*(vertical?.09:.07),headingY=height*(vertical?.2:.19),opacity=Math.min(motion.enter,motion.leave);ctx.save();ctx.fillStyle=theme.background;ctx.fillRect(0,0,width,height);ctx.strokeStyle=theme.accent;ctx.globalAlpha=.18*motion.enter;ctx.lineWidth=Math.max(2,2*scale);ctx.beginPath();ctx.arc(width*1.02,height*.13,width*(vertical?.31:.16),0,Math.PI*2);ctx.stroke();ctx.globalAlpha=opacity;if(scene.transition==='slide')ctx.translate((1-motion.enter)*width*.13-(1-motion.leave)*width*.07,0);if(scene.transition==='zoom'){ctx.translate(width/2,height/2);ctx.scale((.84+motion.enter*.16)*(.96+motion.leave*.04),(.84+motion.enter*.16)*(.96+motion.leave*.04));ctx.translate(-width/2,-height/2)}
 ctx.save();ctx.globalAlpha*=motion.kicker;ctx.translate(0,(1-motion.kicker)*24*scale);ctx.fillStyle=theme.accent;ctx.font=`700 ${Math.round((vertical?30:17)*scale)}px sans-serif`;ctx.letterSpacing=`${Math.round(3*scale)}px`;ctx.fillText(scene.type==='diagram'?'SCHÉMA':scene.type==='chart'?'DONNÉES':scene.type==='summary'?'À RETENIR':'NOCTURNE EXPLIQUE',pad,headingY);ctx.restore();ctx.letterSpacing='0px';
 ctx.save();ctx.globalAlpha*=clamp(motion.title);ctx.translate(0,(1-clamp(motion.title))*45*scale);ctx.fillStyle=theme.foreground;const titleSize=(scene.type==='title'?(vertical?112:72):(vertical?86:54))*scale,titleLine=titleSize*1.08;ctx.font=`600 ${Math.round(titleSize)}px sans-serif`;const titleY=headingY+(vertical?100:55)*scale,titleHeight=wrapped(ctx,scene.title,pad,titleY,width-pad*2,titleLine,4);ctx.restore();const contentY=titleY+titleHeight+(vertical?60:30)*scale;
 if(scene.body){ctx.save();ctx.globalAlpha*=motion.body;ctx.translate(0,(1-motion.body)*38*scale);ctx.fillStyle=scene.type==='quote'?theme.foreground:theme.muted;const bodySize=(scene.type==='quote'?(vertical?62:38):(vertical?43:26))*scale;ctx.font=`400 ${Math.round(bodySize)}px sans-serif`;wrapped(ctx,scene.body,pad,contentY,width-pad*2,bodySize*1.45,7);ctx.restore()}
 if(scene.type==='quote'){ctx.fillStyle=theme.accent;ctx.font=`500 ${Math.round((vertical?30:19)*scale)}px sans-serif`;ctx.fillText('— '+scene.source,pad,height*.75)}if(scene.type==='summary'){ctx.fillStyle=theme.accent;ctx.fillRect(pad*.62,height*.13,Math.max(7,10*scale),height*.7)}if(scene.type==='diagram')drawCanvasDiagram(ctx,scene,width,height,motion.local,theme,scale);if(scene.type==='chart')drawCanvasChart(ctx,scene,width,height,motion.local,theme,scale);ctx.globalAlpha=.35*opacity;ctx.fillStyle=theme.muted;ctx.fillRect(pad,height*.93,width-pad*2,Math.max(2,2*scale));ctx.globalAlpha=opacity;ctx.fillStyle=theme.accent;ctx.fillRect(pad,height*.93,(width-pad*2)*progress,Math.max(3,4*scale));ctx.restore()}
function diagramPositions(count,width,height){return Array.from({length:count},(_,i)=>{const angle=-Math.PI/2+i*Math.PI*2/count;return{x:width*.5+Math.cos(angle)*width*.31,y:height*.62+Math.sin(angle)*height*.17}})}
function drawCanvasDiagram(ctx,scene,width,height,local,theme,scale){const points=diagramPositions(scene.nodes.length,width,height);ctx.lineWidth=Math.max(2,4*scale);ctx.strokeStyle=theme.muted;scene.links.forEach(([a,b],i)=>{const r=clamp((local-.55-i*.12)/.35),from=points[a],to=points[b];ctx.beginPath();ctx.moveTo(from.x,from.y);ctx.lineTo(from.x+(to.x-from.x)*r,from.y+(to.y-from.y)*r);ctx.stroke()});scene.nodes.forEach((item,i)=>{const raw=clamp((local-.4-i*.12)/.32),r=1-(1-raw)**3,point=points[i],w=width*.34,h=height*(height>width*1.2?.085:.13);ctx.save();ctx.globalAlpha*=r;ctx.translate(point.x,point.y);ctx.scale(.72+r*.28,.72+r*.28);ctx.fillStyle=theme.background;ctx.strokeStyle=theme.accent;rounded(ctx,-w/2,-h/2,w,h,18*scale);ctx.fillStyle=theme.foreground;ctx.font=`600 ${Math.round((height>width*1.2?29:18)*scale)}px sans-serif`;ctx.textAlign='center';ctx.textBaseline='middle';wrapped(ctx,item.label,0,-10*scale,w*.82,(height>width*1.2?36:23)*scale,3);ctx.restore()})}
function drawCanvasChart(ctx,scene,width,height,local,theme,scale){const left=width*.1,right=width*.9,top=height*.46,bottom=height*.82,gap=width*.035,max=Math.max(...scene.values.map(v=>v.value),1),barWidth=(right-left-gap*(scene.values.length-1))/scene.values.length,vertical=height>width*1.2;ctx.strokeStyle=theme.muted;ctx.beginPath();ctx.moveTo(left,bottom);ctx.lineTo(right,bottom);ctx.stroke();scene.values.forEach((item,i)=>{const raw=clamp((local-.4-i*.12)/.45),r=1-(1-raw)**3,h=(bottom-top)*(item.value/max*.85+.12)*r,x=left+i*(barWidth+gap);ctx.fillStyle=theme.accent;ctx.fillRect(x,bottom-h,barWidth,h);ctx.textAlign='center';ctx.fillStyle=theme.foreground;ctx.font=`600 ${Math.round((vertical?29:17)*scale)}px sans-serif`;ctx.fillText(`${item.value}${scene.unit?' '+scene.unit:''}`,x+barWidth/2,bottom-h-18*scale);ctx.fillStyle=theme.muted;ctx.font=`400 ${Math.round((vertical?23:13)*scale)}px sans-serif`;wrapped(ctx,item.label,x+barWidth/2,bottom+34*scale,barWidth,(vertical?30:17)*scale,2)});ctx.textAlign='left'}
function videoMime(){return ['video/mp4;codecs=avc1.42E01E','video/webm;codecs=vp9','video/webm;codecs=vp8','video/webm'].find(type=>MediaRecorder.isTypeSupported(type))||''}
async function exportVideo(){const button=$('#export-video'),status=$('#export-status'),dimensions={vertical:[1080,1920],horizontal:[1920,1080],square:[1080,1080]}[project.format],canvas=document.createElement('canvas');canvas.width=dimensions[0];canvas.height=dimensions[1];const ctx=canvas.getContext('2d'),mime=videoMime(),stream=canvas.captureStream(project.fps),chunks=[],recorder=new MediaRecorder(stream,{...(mime?{mimeType:mime}:{}),videoBitsPerSecond:8_000_000});button.disabled=true;$('#play').disabled=true;playing=false;cancelAnimationFrame(raf);status.textContent='Préparation de la vidéo…';recorder.ondataavailable=event=>{if(event.data.size)chunks.push(event.data)};const done=new Promise((resolve,reject)=>{recorder.onstop=resolve;recorder.onerror=()=>reject(recorder.error||Error('Export impossible'))});recorder.start(1000);const started=performance.now();await new Promise(resolve=>{const frame=now=>{const time=Math.min(project.duration,(now-started)/1000);canvasScene(ctx,canvas.width,canvas.height,time);status.textContent=`Rendu vidéo : ${Math.round(time/project.duration*100)} %`;if(time<project.duration)requestAnimationFrame(frame);else resolve()};requestAnimationFrame(frame)});recorder.stop();await done;stream.getTracks().forEach(track=>track.stop());const type=recorder.mimeType||mime||'video/webm',extension=type.startsWith('video/mp4')?'mp4':'webm',blob=new Blob(chunks,{type}),link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download=`${slug()}.${extension}`;link.click();setTimeout(()=>URL.revokeObjectURL(link.href),2000);status.textContent=`Vidéo ${extension.toUpperCase()} téléchargée · ${(blob.size/1024/1024).toFixed(1)} Mo.`;button.disabled=false;$('#play').disabled=false}
$('#export-video').addEventListener('click',()=>exportVideo().catch(error=>{$('#export-status').textContent='Export impossible : '+error.message;$('#export-video').disabled=false;$('#play').disabled=false}));
$('#video-form').addEventListener('submit',async event=>{event.preventDefault();$('#generate').disabled=true;$('#message').className='workshop-message';$('#message').textContent='Ollama prépare le storyboard…';try{const result=await request('/api/videos/generate',{method:'POST',body:{model:$('#model').value,subject:$('#subject').value,format:$('#format').value,audience:$('#audience').value,tone:$('#tone').value},timeoutMs:260000});load(result);$('#message').textContent='Storyboard généré, validé et sauvegardé.';await loadSaved()}catch(e){$('#message').textContent=e.message;$('#message').classList.add('error')}finally{$('#generate').disabled=false}});
async function loadSaved(){const items=await request('/api/videos');const root=$('#saved-videos');if(!items.length){root.innerHTML='<p class="field-hint">Aucun storyboard généré.</p>';return}root.replaceChildren(...items.map(item=>{const row=node('div');row.append(node('strong','',item.title),node('span','',`${item.format} · ${item.duration.toFixed(1)} s`));const button=node('button','quiet','Ouvrir');button.addEventListener('click',async()=>load(await request('/api/videos/'+item.id)));row.append(button);return row}))}
bindModelRefresh(refreshStatus);refreshStatus().catch(e=>{$('#connection-state').textContent=e.message;$('#connection-state').classList.add('error')});loadSaved().catch(()=>{$('#saved-videos').innerHTML='<p class="field-hint">Impossible de lire les projets.</p>'});
